using UnityEngine; public class GravityInversionField : MonoBehaviour { private void OnTriggerEnter(Collider other) { if (other.CompareTag("Coin")) { Rigidbody rb = other.GetComponent<Rigidbody>(); if (rb != null) { rb.useGravity = false; rb.AddForce(Vector3.up * 20f, ForceMode.Impulse); } } } private void OnTriggerExit(Collider other) { if (other.CompareTag("Coin")) { Rigidbody rb = other.GetComponent<Rigidbody>(); if (rb != null) { rb.useGravity = true; } } } }